const setPoolConfigurationAssignment = `-- name: SetPoolConfigurationAssignment :one
WITH discarded AS (
 DELETE FROM pool_configuration_board_intent p USING pool_configuration_assignment a
 WHERE a.organization_id=$1 AND a.target_kind=$2 AND a.target_id=$3 AND a.retired_at IS NOT NULL
  AND p.organization_id=a.organization_id AND p.installation_id=a.target_id AND a.target_kind='hashboard_installation'
)
INSERT INTO pool_configuration_assignment(organization_id, target_kind, target_id, device_id, configuration_id, revision_id, version, operation_id)
VALUES($1, $2, $3, $4, $5, $6, 1, $7)
ON CONFLICT (organization_id, target_kind, target_id) DO UPDATE SET
 configuration_id = EXCLUDED.configuration_id, revision_id = EXCLUDED.revision_id,
 version = pool_configuration_assignment.version + 1, operation_id = EXCLUDED.operation_id,
 retired_at = NULL, updated_at = CURRENT_TIMESTAMP
RETURNING organization_id, target_kind, target_id, device_id, configuration_id, revision_id, version, operation_id, retired_at, updated_at, adopted_at
`

type SetPoolConfigurationAssignmentParams struct {
	OrganizationID  int64
	TargetKind      string
	TargetID        int64
	DeviceID        int64
	ConfigurationID string
	RevisionID      string
	OperationID     sql.NullString
}

// Explicitly returning retired equipment must not resurrect its former intent
// while the new reviewed operation is pending or if admission later fails.
func (q *Queries) SetPoolConfigurationAssignment(ctx context.Context, arg SetPoolConfigurationAssignmentParams) (PoolConfigurationAssignment, error) {
	row := q.queryRow(ctx, q.setPoolConfigurationAssignmentStmt, setPoolConfigurationAssignment,
		arg.OrganizationID,
		arg.TargetKind,
		arg.TargetID,
		arg.DeviceID,
		arg.ConfigurationID,
		arg.RevisionID,
		arg.OperationID,
	)
	var i PoolConfigurationAssignment
	err := row.Scan(
		&i.OrganizationID,
		&i.TargetKind,
		&i.TargetID,
		&i.DeviceID,
		&i.ConfigurationID,
		&i.RevisionID,
		&i.Version,
		&i.OperationID,
		&i.RetiredAt,
		&i.UpdatedAt,
		&i.AdoptedAt,
	)
	return i, err
}

const supersedePoolConfigurationTarget = `-- name: SupersedePoolConfigurationTarget :exec
UPDATE pool_configuration_operation_target SET state = 'superseded', updated_at = CURRENT_TIMESTAMP
WHERE organization_id = $1 AND target_kind = $2 AND target_id = $3 AND state IN ('pending','applying','failed','different','applied_unverified')
`

type SupersedePoolConfigurationTargetParams struct {
	OrganizationID int64
	TargetKind     string
	TargetID       int64
}

func (q *Queries) SupersedePoolConfigurationTarget(ctx context.Context, arg SupersedePoolConfigurationTargetParams) error {
	_, err := q.exec(ctx, q.supersedePoolConfigurationTargetStmt, supersedePoolConfigurationTarget, arg.OrganizationID, arg.TargetKind, arg.TargetID)
	return err
}
